mapper.update:
update builder.adk_builder_frd_screen
   set excluded_at = null
 where frd_id = #{frdId}
   and screen_id = #{screenId}
   and excluded_at is not null

update builder.adk_builder_frd_screen
   set state = #{state}
 where id = #{id}

update builder.adk_builder_frd_screen
   set html = #{html}, changes = #{changes,jdbcType=VARCHAR},
       failure = null, state = 'GENERATED', generated_at = #{generatedAt}
 where id = #{id}

update builder.adk_builder_frd_screen
   set failure = #{failure,jdbcType=VARCHAR}, state = 'FAILED'
 where id = #{id}

update builder.adk_builder_frd_screen
   set base_screen_id = #{baseScreenId}
 where id = #{id}
   and base_screen_id is null

update builder.adk_builder_frd_screen
   set system_code = #{systemCode}
 where id = #{id}
   and (system_code is null or btrim(system_code) = '')

update builder.adk_builder_frd_screen
   set scope_change = #{scopeChange,jdbcType=VARCHAR}
 where id = #{id}
